/** 内置需求模板库：5 类必备模板（场景/计算/算法/状态机/混合）。
 *
 * 模板正文为 Polarion HTML 子集（与工作项正文同构），完整支持侧边栏副文本编辑；
 * 结构蓝本取自 B14 项目（45_SPE25_BQ1_TM_002）真实需求工作项，变量命名遵循
 * 《SPE-TMS-汽车热管理变量命名规范》V2.1（指令库同源规范）。
 *
 * 分层：本文件是「软件默认」基线；个人覆盖与自定义模板存本机 Host（req-template），
 * 读取时合并：本地覆盖 > 代码内置基线；新装机读到标准模板。 */

/** 模板类别。 */
export type RequirementTemplateCategory = 'scenario' | 'calculation' | 'algorithm' | 'state-machine' | 'hybrid';

/** 内置模板记录（软件默认基线）。 */
export type BuiltinRequirementTemplate = {
  id: string;
  category: RequirementTemplateCategory;
  name: string;
  /** 该模板在什么情况下使用（模板库悬浮页展示）。 */
  usageNote: string;
  /** 内置基线版本；软件更新丰富模板时递增。 */
  version: number;
  html: string;
};

/** 类别展示信息（图标 key、副标题、使用时机文案共用）。 */
export const templateCategories: { key: RequirementTemplateCategory; label: string; hint: string }[] = [
  { key: 'scenario', label: '场景类', hint: '介入/退出型功能：开关、一键类、远程、模式请求等事件驱动场景' },
  { key: 'calculation', label: '计算类', hint: '查表/公式型计算：目标出风温度、风量、水流量、过冷过热度等' },
  { key: 'algorithm', label: '算法类', hint: '闭环/策略算法：PID、MPC、前馈+反馈、仲裁打分等参数整定类' },
  { key: 'state-machine', label: '状态机类', hint: '多状态跳转：上下电、充电、热管理模式、故障分级等' },
  { key: 'hybrid', label: '混合类', hint: '复合逻辑：AUTO 空调、热源选择等同时涉及场景+计算+状态机的功能' },
];

/** 通用接口表列头（与 B14 真实需求一致；输入/输出分表后省去方向列）。 */
const signalHead = '<tr><th style="background-color: #F0F0F0;text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;">信号名称</th><th style="background-color: #F0F0F0;text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;">信号描述</th><th style="background-color: #F0F0F0;text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;">信号值</th><th style="background-color: #F0F0F0;text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;">信号源<br/>（CAN/LIN/硬线/内部信号）</th><th style="background-color: #F0F0F0;text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;">相关工作项</th></tr>';

/** 占位引导段落。 */
function hint(text: string): string {
  return `<p><em>${text}</em></p>`;
}

/** 占位表格空行。 */
function emptyRow(cells: number): string {
  return `<tr>${'<td style="text-align: left;vertical-align: top;border: 1px solid #CCCCCC;padding: 5px;"><br/></td>'.repeat(cells)}</tr>`;
}

