/** 内置模板基线（软件默认；更新软件时在此丰富并递增 version）。 */
export const builtinRequirementTemplates: BuiltinRequirementTemplate[] = [
  { id: 'req-tpl-scenario', category: 'scenario', name: '场景类需求模板', usageNote: '介入/退出型功能：开关、一键类（一键凉爽/加热/除霜）、远程空调、钥匙远程、模式请求等事件驱动场景。含进入/退出条件与动作分支。', version: 1, html: scenarioHtml },
  { id: 'req-tpl-calculation', category: 'calculation', name: '计算类需求模板', usageNote: '查表/公式型计算：目标出风温度、风量、水流量、过冷过热度、负荷需求等。含公式、查表、变量表与边界保护。', version: 1, html: calculationHtml },
  { id: 'req-tpl-algorithm', category: 'algorithm', name: '算法类需求模板', usageNote: '闭环/策略算法：PID、MPC、前馈+反馈、仲裁打分等需要参数整定与性能指标的控制算法。', version: 1, html: algorithmHtml },
  { id: 'req-tpl-state-machine', category: 'state-machine', name: '状态机类需求模板', usageNote: '多状态跳转：上下电时序、充电状态、热管理模式仲裁、故障分级等互斥状态集合。含状态定义表与跳转表。', version: 1, html: stateMachineHtml },
  { id: 'req-tpl-hybrid', category: 'hybrid', name: '混合类需求模板', usageNote: '复合逻辑：AUTO 空调、热源选择、热泵模式等同时涉及场景、计算与状态机的功能。先分解子功能再按类别展开。', version: 1, html: hybridHtml },
];

/** 按 id 取内置模板。 */
export function builtinTemplateById(id: string): BuiltinRequirementTemplate | undefined {
  return builtinRequirementTemplates.find(template => template.id === id);
}
